pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock ERC20 that has both transferFrom and transfer
        // The mock will revert on transferFrom but succeed on transfer
        address mock = address(new MockERC20(true, false));
        address from = address(1);
        address[] memory tos = new address[](1);
        tos[0] = address(2);
        uint v = 100;

        bool ok;
        try c.transfer(from, mock, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Expected reference to revert but it succeeded");
    }
}

contract MockERC20 {
    bool public revertTransferFrom;
    bool public revertTransfer;

    constructor(bool _revertTransferFrom, bool _revertTransfer) {
        revertTransferFrom = _revertTransferFrom;
        revertTransfer = _revertTransfer;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        require(!revertTransferFrom, "transferFrom revert");
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        require(!revertTransfer, "transfer revert");
        return true;
    }

    // Fallback to catch any unexpected calls
    fallback() external {}
}

